// Comparación mensual de un trabajo por lotes: 5 instancias, 120 horas cada una.
// Precios FICTICIOS del enunciado (USD por hora-instancia); no son precios de AWS.
export const precios = [
  { item: "bajo-demanda", unit: "hora-instancia", pricePerUnitUsd: 0.1 },
  { item: "spot", unit: "hora-instancia", pricePerUnitUsd: 0.04 },
];

export const usoBajoDemanda = [{ item: "bajo-demanda", quantity: 5 * 120 }];
export const usoSpot = [{ item: "spot", quantity: 5 * 120 }];

spec.code:
const r = aws.cost.estimate({ priceTable: precios, usage: usoBajoDemanda });
assert.deepStrictEqual(r.problems, []);
assert.strictEqual(r.totalUsd, 60, "El costo bajo demanda del lote debe ser de 60 USD");

assert.deepStrictEqual(precios, [
  { item: "bajo-demanda", unit: "hora-instancia", pricePerUnitUsd: 0.1 },
  { item: "spot", unit: "hora-instancia", pricePerUnitUsd: 0.04 },
]);

const r = aws.cost.estimate({ priceTable: precios, usage: usoSpot });
assert.deepStrictEqual(r.problems, []);
assert.strictEqual(r.totalUsd, 24, "El costo en Spot del lote debe ser de 24 USD");

for (const uso of [usoBajoDemanda, usoSpot]) {
  assert.strictEqual(uso.length, 1);
  assert.strictEqual(uso[0]?.quantity, 600, "El uso debe contar 5 instancias por 120 horas");
}

