  priceTable: [
    { item: "bajo-demanda", unit: "hora-instancia", pricePerUnitUsd: 0.1 },
    { item: "reservada", unit: "hora-instancia", pricePerUnitUsd: 0.06 },
    { item: "spot", unit: "hora-instancia", pricePerUnitUsd: 0.03 },
  ],
  usage: [
    { item: "reservada", quantity: 3 * 720 },
    { item: "spot", quantity: 400 },
    { item: "bajo-demanda", quantity: 100 },
  ],
};

spec.code:
const r = aws.cost.estimate(plan);
assert.deepStrictEqual(r.problems, []);
assert.strictEqual(r.lines.length, 3, "El plan debe usar una opción de compra por carga");

const r = aws.cost.estimate(plan);
assert.ok(r.lines.length > 0, "El plan no tiene ningún uso");
assert.ok(r.totalUsd <= 160, "El plan cuesta " + r.totalUsd + " USD y el presupuesto es de 160");

assert.deepStrictEqual(plan.priceTable, [
  { item: "bajo-demanda", unit: "hora-instancia", pricePerUnitUsd: 0.1 },
  { item: "reservada", unit: "hora-instancia", pricePerUnitUsd: 0.06 },
  { item: "spot", unit: "hora-instancia", pricePerUnitUsd: 0.03 },
]);

