// Opción de compra que elige un asistente para ocho cargas. Corrige la elección equivocada.
export const compras = {
  casos: [
    { necesidad: "Servicio de pagos que no puede interrumpirse, con demanda impredecible y sin compromiso de plazo", opcion: "bajo-demanda" },
    { necesidad: "Análisis de datos nocturno que puede esperar capacidad libre y reanudarse tras una interrupción", opcion: "spot" },
    { necesidad: "Uso constante durante tres años con cambios frecuentes de familia, tamaño y región de las instancias", opcion: "savings-plans" },
    { necesidad: "Uso constante durante un año con un tipo de instancia y una región que no cambiarán", opcion: "reservadas" },
    { necesidad: "Licencias de software por socket y por núcleo que ya posee la empresa y quiere usar en EC2", opcion: "hosts-dedicados" },
    { necesidad: "Tareas opcionales en segundo plano que pueden pararse sin consecuencias", opcion: "spot" },
    { necesidad: "Uso constante de funciones Lambda y contenedores Fargate que se quiere comprometer por hora", opcion: "savings-plans" },
    { necesidad: "Prueba de concepto de unos días en la que nadie sabe cuántas instancias harán falta", opcion: "bajo-demanda" },
  ],
};

spec.code:
const fila = compras.casos.find((f) => f.necesidad.startsWith("Servicio de pagos"));
assert.ok(fila, "debe existir la fila del servicio de pagos");
assert.strictEqual(fila.opcion, "bajo-demanda");

for (const fila of compras.casos) {
  assert.ok(["bajo-demanda", "savings-plans", "reservadas", "spot", "hosts-dedicados"].includes(fila.opcion), fila.necesidad + " tiene una opción no válida");
}

const esperado: Record<string, string> = {
  "Análisis de datos nocturno que puede esperar capacidad libre y reanudarse tras una interrupción": "spot",
  "Uso constante durante tres años con cambios frecuentes de familia, tamaño y región de las instancias": "savings-plans",
  "Uso constante durante un año con un tipo de instancia y una región que no cambiarán": "reservadas",
  "Licencias de software por socket y por núcleo que ya posee la empresa y quiere usar en EC2": "hosts-dedicados",
  "Tareas opcionales en segundo plano que pueden pararse sin consecuencias": "spot",
  "Uso constante de funciones Lambda y contenedores Fargate que se quiere comprometer por hora": "savings-plans",
  "Prueba de concepto de unos días en la que nadie sabe cuántas instancias harán falta": "bajo-demanda",
};
for (const [necesidad, opcion] of Object.entries(esperado)) {
  const fila = compras.casos.find((f) => f.necesidad === necesidad);
  assert.ok(fila, necesidad + " debe seguir existiendo");
  assert.strictEqual(fila.opcion, opcion);
}
